package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 应用基础配置：提供可替换的时钟，便于测试使用可控时钟。
 */
@Configuration
public class AppConfig {

    /**
     * 系统时钟（UTC），测试中可覆盖为固定时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.plan;

/**
 * 放疗计划状态机：设计→物理审核→医师批准→首次验证→分次执行→疗程结案；
 * INVALIDATED 表示被新版本替代即刻失效。
 */
public enum PlanStatus {
    /** 设计中，可提交物理审核 */
    DESIGN,
    /** 物理审核通过，可提交医师批准 */
    PHYSICS_REVIEWED,
    /** 医师已批准，可提交首次模体验证 */
    APPROVED,
    /** 首次验证通过，可开始分次执行 */
    VERIFIED,
    /** 分次执行中 */
    EXECUTING,
    /** 疗程结案，终态 */
    CLOSED,
    /** 已失效（换版后旧版本） */
    INVALIDATED
}

package com.example.starter.plan;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码与稳定错误码。
 * 409 用于幂等冲突与状态冲突，422 用于业务规则校验失败。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    /** 幂等冲突：同键异参 */
    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, "CONFLICT", message);
    }

    /** 状态机不允许的流转 */
    public static ApiException invalidState(String message) {
        return new ApiException(HttpStatus.CONFLICT, "INVALID_STATE", message);
    }

    /** 业务规则校验失败（剂量超限、跳次等） */
    public static ApiException unprocessable(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "BUSINESS_RULE_VIOLATION", message);
    }

    /** 资源不存在 */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }
}

